CREATE TABLE `payments` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`appointment_id` BIGINT UNSIGNED NOT NULL,`method` ENUM('CASH', 'PIX', 'DEBIT_CARD', 'CREDIT_CARD', 'BANK_TRANSFER', 'OTHER') NOT NULL,`status` ENUM('PAID', 'CANCELED') NOT NULL DEFAULT 'PAID',`amount_cents` BIGINT UNSIGNED NOT NULL,`notes` VARCHAR(500) NULL,`user_id` BIGINT UNSIGNED NULL,`session_id` BIGINT UNSIGNED NULL,`canceled_at` DATETIME(3) NULL,`canceled_reason` VARCHAR(500) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `payments_public_id_key` (`public_id`),INDEX `payments_tenant_id_appointment_id_created_at_idx` (`tenant_id`,`appointment_id`,`created_at`),INDEX `payments_tenant_id_status_created_at_idx` (`tenant_id`,`status`,`created_at`),CONSTRAINT `payments_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `payments_appointment_id_fkey` FOREIGN KEY (`appointment_id`) REFERENCES `appointments`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `payments_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `payments_session_id_fkey` FOREIGN KEY (`session_id`) REFERENCES `user_sessions`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
